// @ts-nocheck
// Hairline figure "hatch" for brijmohan-valentine-monster-4p. Generated by the murder-mystery-story-tree skill via hairline-create.
// Body is the figure file verbatim; edit with: python scripts/art.py unwrap <this> hatch.js → look.mjs → wrap.
export default function define(HL, hairline) {
/**
 * Hatch: a cellar trapdoor cut into a plank floor, left ajar on a dark gap.
 * The pointer lifts it on its hinge, on a spring: the steps drop away into
 * the dark below, and at the bottom a fire iron lies across the last step.
 * The slider is how far the hatch can swing back, in degrees.
 * The pointer is read against the hatch's shut and open edges on screen,
 * which never move. The floor is painted over the stairwell with the hole cut
 * out of it, so only what the opening shows is seen.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, seg,
  spring, stepS, mk, pointer, register, disposer,
} = HL;

const FX = 130, FY = 120, FT = 10;              // floor
const HX0 = 30, HX1 = 100, HY0 = 24, HY1 = 96;  // the hole
const LW = HX1 - HX0, LD = HY1 - HY0, TH = 3;   // the hatch
const RISE = 8, TREAD = 14, STEPS = 3, AJAR = 5;
const LID = rrect(0, 0, LW, LD, 2, 3);
const area = (pts) => pts.reduce((s, p, i) => { const q = pts[(i + 1) % pts.length]; return s + p[0] * q[1] - q[0] * p[1]; }, 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, -FT], [FX, FY, -FT], [FX, 0, -FT], [0, FY, -FT], [HX0, HY0, LW], [HX0, HY1, LW], [HX0 - 35, HY0, 61], [HX0 - 35, HY1, 61]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // The stairwell: three steps down from under the hinge toward us, then the dark. Each step is a block, far to
  // near, the deeper the dimmer, cut short past where the near walls hide it (depth d hides x, y > H1 - d / 0.816).
  const well = mk("g", {}, g);
  mk("path", { d: seg(P(HX0, HY0, 0), P(HX0, HY0, -RISE)), class: "nf lo" }, well);
  const x = (k) => HX0 + TREAD * k;
  for (let k = 1; k <= STEPS; k++) {
    const z = -RISE * k, hide = (RISE - z) / 0.816 - 6;
    const [r, i] = rings(x(k - 1), HY0, Math.min(x(k), HX1 - hide), Math.min(HY1, HY1 - hide), 1.2, 0.7), q = prism(P, front, r, i, z - RISE, z);
    mk("path", { d: q.sil, class: k > 2 ? "lo" : "" }, well);
    mk("path", { d: q.crease, class: "nf lo" }, well);
  }
  // The fire iron across the bottom step: a rod, its hook at the far end, its grip loop at the near.
  const zi = -RISE * STEPS + 0.4, ix = x(STEPS - 1) + 3;
  const iron = mk("path", {
    d: open([P(ix + 3.5, HY0 + 3, zi), P(ix + 0.5, HY0 + 4.5, zi), P(ix, HY0 + 8, zi), P(ix + 4, HY0 + 28, zi)]) +
      poly(rrect(-2.2, -3, 2.2, 3, 2, 3).map((q) => P(ix + 4.4 + q.u, HY0 + 31 + q.v, zi))),
    class: "nf",
  }, well);

  // The floor, with the hole cut out of it: one plate, filled only, over the stairwell. Then its lines.
  const [fr, fi] = rings(0, 0, FX, FY, 6, 2);
  const outline = hull(ringAt(P, fr, -FT).concat(ringAt(P, fr, 0)));
  const hole = ringAt(P, rrect(HX0, HY0, HX1, HY1, 1.5, 2), 0);
  const cut = Math.sign(area(outline)) === Math.sign(area(hole)) ? hole.slice().reverse() : hole;
  mk("path", { d: poly(outline) + poly(cut), class: "fo" }, g);
  const fl = prism(P, front, fr, fi, -FT, 0);
  mk("path", { d: fl.sil, class: "nf sil" }, g);
  mk("path", { d: fl.crease, class: "nf lo" }, g);
  mk("path", { d: poly(hole), class: "nf" }, g);
  // The trim round the opening, and the floor leaves of the two strap hinges.
  let seams = poly(ringAt(P, rrect(HX0 - 3, HY0 - 3, HX1 + 3, HY1 + 3, 3, 3), 0)) +
    [10, LD - 10].map((v) => poly([P(HX0 - 9, HY0 + v - 2, 0), P(HX0 - 3, HY0 + v - 2, 0), P(HX0 - 3, HY0 + v + 2, 0), P(HX0 - 9, HY0 + v + 2, 0)])).join("");
  for (let y = 12; y < FY; y += 12) {
    const runs = y >= HY0 - 3 && y <= HY1 + 3 ? [[3, HX0 - 3], [HX1 + 3, FX - 3]] : [[3, FX - 3]];
    for (const [a, b] of runs) seams += seg(P(a, y, 0), P(b, y, 0));
  }
  mk("path", { d: seams, class: "nf lo" }, g);

  // The hatch: two faces a board apart, the lip at its free edge, and the marks of whichever face we see.
  const lid = mk("g", {}, g);
  const hidden = mk("path", { class: "lo" }, lid), shown = mk("path", {}, lid);
  const marks = mk("path", { class: "nf lo" }, lid), lip = mk("path", { class: "hi" }, lid);
  let drawn = NaN;
  function draw(a) {
    if (a === drawn) return;
    drawn = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const top = (u, v) => P(HX0 + u * c, HY0 + v, u * s);
    const bot = (u, v) => P(HX0 + u * c + TH * s, HY0 + v, u * s - TH * c);
    const up = a < 39, see = up ? top : bot;
    hidden.setAttribute("d", poly(LID.map((q) => (up ? bot : top)(q.u, q.v))));
    shown.setAttribute("d", poly(LID.map((q) => see(q.u, q.v))));
    lip.setAttribute("d", poly([top(LW, 1), top(LW, LD - 1), bot(LW, LD - 1), bot(LW, 1)]));
    // Top: the floorboards run on across it, the hinge straps and a ring pull. Underside: two battens and a brace.
    marks.setAttribute("d", up
      ? [12, 24, 36, 48, 60].map((v) => seg(see(1.5, v), see(LW - 1.5, v))).join("") + poly(rrect(-3.5, -3.5, 3.5, 3.5, 3.5, 3).map((q) => see(LW - 8 + q.u, LD / 2 + q.v))) +
        [10, LD - 10].map((v) => poly([see(0.5, v - 2), see(20, v - 2), see(20, v + 2), see(0.5, v + 2)])).join("")
      : [8, LW - 13].map((u) => poly([see(u, 3), see(u + 5, 3), see(u + 5, LD - 3), see(u, LD - 3)])).join("") + seg(see(13, LD - 4), see(LW - 13, 4)));
  }

  const sp = spring(AJAR, { eps: 0.05 });
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  // The pull: from the free edge shut to the free edge at full swing, both fixed points on screen.
  let A0, A1;
  const edge = (a) => P(HX0 + LW * Math.cos(rad(a)), HY0 + LD / 2, LW * Math.sin(rad(a)));
  const aim = () => { A0 = edge(0); A1 = edge(MAX); };
  aim();
  let revealed = false, last = null;
  function lift(p) {
    last = p;
    let t = null;
    if (p) {
      const dx = A1[0] - A0[0], dy = A1[1] - A0[1];
      t = clamp(((p[0] - A0[0]) * dx + (p[1] - A0[1]) * dy) / (dx * dx + dy * dy), 0, 1);
    }
    sp.t = t == null ? AJAR : t * MAX;
    const r = t != null && t >= 0.85;
    if (r !== revealed) { revealed = r; lip.classList.toggle("hi", !r); iron.classList.toggle("hi", r); }
    read.textContent = t == null ? "rest" : t < 0.06 ? "shut" : t < 0.5 ? "ajar" : t < 0.85 ? "open" : "the bottom step";
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => lift(p), leave: () => lift(null) }));
  bag.add(() => svg.replaceChildren());

  return {
    set: (v) => { MAX = v; aim(); if (last) lift(last); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "hatch",
  means: "A cellar hatch left ajar in a plank floor: lift it and the steps drop into the dark, a fire iron on the last one.",
  rules: [1, 4, 5, 6],
  range: [90, 105, 120],
  tour: [[250, 231], [200, 157], [125, 49], null],
  mount,
});
}
